-- The Casino page of the in-game menu: table picker, spinning wheel, betting board, seats and the player's bets.
-- Layout lives in gui/CasinoFrame.xml (generated by tools/gen_frame.py).

CasinoFrame = {}
local CasinoFrame_mt = Class(CasinoFrame, TabbedMenuFrameElement)

CasinoFrame.NUM_HISTORY = 12
CasinoFrame.NUM_BET_LINES = 10
CasinoFrame.NUM_CHIPS = 4
CasinoFrame.SPIN_REST_TIME = 1200 -- ms the wheel rests on the result before the spin phase ends
CasinoFrame.WHEEL_LAPS = 2
CasinoFrame.BALL_LAPS = 5

CasinoFrame.COLORS = {
    red = {0.62, 0.07, 0.07, 1},
    black = {0.06, 0.06, 0.06, 1},
    green = {0.03, 0.45, 0.16, 1}
}
CasinoFrame.HUB_COLORS = {
    red = {1, 0.35, 0.35, 1},
    black = {1, 1, 1, 1},
    green = {0.3, 1, 0.5, 1}
}

local TWO_PI = 2 * math.pi
local POCKET_ANGLE = TWO_PI / 37

CasinoFrame.CELL_KEYS = {"col1", "col2", "col3", "doz1", "doz2", "doz3", "low", "even", "red", "black", "odd", "high"}
for n = 0, 36 do
    table.insert(CasinoFrame.CELL_KEYS, "n" .. n)
end

local function getText(key)
    return g_i18n:getText(key)
end

local function formatMoney(value)
    return g_i18n:formatMoney(value, 0, true, true)
end

---Compact amount for board cells and chips: 500, 25k, 1.5M
function CasinoFrame.formatShort(value)
    local function trim(v)
        return (string.gsub(string.format("%.1f", v), "%.0$", ""))
    end
    if value >= 1000000 then
        return trim(value / 1000000) .. "M"
    elseif value >= 1000 then
        return trim(value / 1000) .. "k"
    end
    return tostring(value)
end

function CasinoFrame.new(casino)
    local self = TabbedMenuFrameElement.new(nil, CasinoFrame_mt)

    self.casino = casino
    self.tableId = 1
    self.chipIndex = 1
    self.lastBets = {} -- [tableId] = bets of the local player's last finished round, for "Repeat bets"
    self.lastStatus = nil
    self.lastHub = nil

    self:setMenuButtonInfo({
        {inputAction = InputAction.MENU_BACK}
    })

    return self
end

function CasinoFrame:copyAttributes(src)
    CasinoFrame:superClass().copyAttributes(self, src)
    self.casino = src.casino
end

function CasinoFrame:onGuiSetupFinished()
    CasinoFrame:superClass().onGuiSetupFinished(self)

    self.cells = {}
    for _, key in ipairs(CasinoFrame.CELL_KEYS) do
        local root = self:getDescendantById("casinoCell_" .. key)
        if root ~= nil then
            local cell = {
                root = root,
                win = root:getDescendantByName("win"),
                stake = root:getDescendantByName("stake"),
                dots = {}
            }
            for s = 1, RouletteTable.NUM_SEATS do
                cell.dots[s] = root:getDescendantByName("dot" .. s)
            end
            self.cells[key] = cell
        end
    end

    self.wheel = self:getDescendantById("casinoWheel")
    self.ball = self:getDescendantById("casinoBall")
    self.hubText = self:getDescendantById("casinoHubText")
    CasinoFrame.setTexture(self.wheel, "images/wheel.dds")
    CasinoFrame.setTexture(self.ball, "images/ball.dds")

    self.historyCells = {}
    for h = 1, CasinoFrame.NUM_HISTORY do
        local root = self:getDescendantById("casinoHist" .. h)
        self.historyCells[h] = {root = root, label = root:getDescendantByName("label")}
    end

    self.seatRows = {}
    for s = 1, RouletteTable.NUM_SEATS do
        local root = self:getDescendantById("casinoSeat" .. s)
        local leave = self:getDescendantById("casinoLeaveBtn" .. s)
        CasinoFrame.setTexture(leave:getDescendantByName("icon"), "images/leave.dds")
        self.seatRows[s] = {
            root = root,
            swatch = root:getDescendantByName("swatch"),
            name = root:getDescendantByName("name"),
            info = root:getDescendantByName("info"),
            hit = root:getDescendantByName("s" .. s),
            leave = leave
        }
    end

    self.tableButtons = {}
    for t = 1, #Casino.TABLES do
        self.tableButtons[t] = self:getDescendantById("casinoTableBtn" .. t)
    end
    self.chipButtons = {}
    for c = 1, CasinoFrame.NUM_CHIPS do
        self.chipButtons[c] = self:getDescendantById("casinoChipBtn" .. c)
    end
    self.betLines = {}
    for b = 1, CasinoFrame.NUM_BET_LINES do
        self.betLines[b] = self:getDescendantById("casinoBetLine" .. b)
    end

    self.clearButton = self:getDescendantById("casinoClearBtn")
    self.rebetButton = self:getDescendantById("casinoRebetBtn")
    self.statusText = self:getDescendantById("casinoStatusText")
    self.messageText = self:getDescendantById("casinoMessageText")
    self.accessText = self:getDescendantById("casinoAccessText")
    self.balanceText = self:getDescendantById("casinoBalanceText")
    self.stakeText = self:getDescendantById("casinoStakeText")
end

---Shows one of the mod's textures, full size, on a Bitmap
function CasinoFrame.setTexture(bitmap, path)
    bitmap:setImageFilename(Utils.getFilename(path, Casino.dir))
    bitmap:setImageUVs(nil, 0, 0, 0, 1, 1, 0, 1, 1)
end

function CasinoFrame:onFrameOpen()
    CasinoFrame:superClass().onFrameOpen(self)
    self.casino:tick()
    self:refresh()
end

function CasinoFrame:update(dt)
    CasinoFrame:superClass().update(self, dt)
    self.casino:tick()
    self:updateDynamic()
end

function CasinoFrame:getTable()
    return self.casino:getTable(self.tableId)
end

function CasinoFrame:onTableChanged(rouletteTable)
    -- remember the local player's bets of a finished round for "Repeat bets"
    local userId = g_currentMission.playerUserId
    local seat = rouletteTable:findSeat(userId)
    if seat ~= nil and rouletteTable.phase ~= RouletteTable.PHASE.BETTING then
        local mine = {}
        for _, bet in ipairs(rouletteTable.bets) do
            if bet.seat == seat then
                table.insert(mine, {kind = bet.kind, base = bet.base, amount = bet.amount})
            end
        end
        if #mine > 0 then
            self.lastBets[rouletteTable.id] = mine
        end
    end

    if self.cells ~= nil then
        self:refresh()
    end
end

function CasinoFrame:updateMessage()
    if self.messageText ~= nil then
        local message = self.casino.message
        self.messageText:setText(message ~= nil and message.text or "")
    end
end

local function resultLabel(n)
    if n < 0 then
        return ""
    end
    return string.format("%d %s", n, getText("casino_color_" .. RouletteRules.getColor(n)))
end

function CasinoFrame:getStatusText(rouletteTable)
    local PHASE = RouletteTable.PHASE
    if rouletteTable.phase == PHASE.BETTING then
        return string.format(getText("casino_phase_betting"), math.ceil(rouletteTable.timer / 1000))
    elseif rouletteTable.phase == PHASE.SPINNING then
        return getText("casino_phase_spinning")
    elseif rouletteTable.phase == PHASE.RESULT then
        return string.format(getText("casino_phase_result"), resultLabel(rouletteTable.result))
    end
    return getText("casino_phase_idle")
end

---Rotation (radians, counter-clockwise) that puts number n under the pointer. The wheel texture has pocket i of the
-- wheel order i-1 steps clockwise from the top.
local function getPocketRotation(n)
    return (RouletteRules.getWheelIndex(n) - 1) * POCKET_ANGLE
end

---Wheel and ball rotation for the current moment. Every client computes the same angles from the shared timer:
-- while betting the wheel turns slowly (one lap per betting time, so restarts don't jump); during the spin the wheel
-- turns counter-clockwise and the ball clockwise, both easing out so the result ends under the pointer.
-- @return wheelRotation, ballRotation or nil when the ball is not on the wheel
function CasinoFrame:getWheelRotation(rouletteTable)
    local PHASE = RouletteTable.PHASE
    local rest = getPocketRotation(rouletteTable.history[1] or 0)

    if rouletteTable.phase == PHASE.BETTING then
        local elapsed = RouletteTable.BETTING_TIME - rouletteTable.timer
        return rest + TWO_PI * elapsed / RouletteTable.BETTING_TIME, nil
    elseif rouletteTable.phase == PHASE.SPINNING and rouletteTable.result >= 0 then
        local duration = RouletteTable.SPIN_TIME - CasinoFrame.SPIN_REST_TIME
        local t = math.max(0, math.min(1, (RouletteTable.SPIN_TIME - rouletteTable.timer) / duration))
        local turn = TWO_PI * CasinoFrame.WHEEL_LAPS + (getPocketRotation(rouletteTable.result) - rest) % TWO_PI
        local wheel = rest + turn * (1 - (1 - t) ^ 3)
        local ball = math.pi - (TWO_PI * CasinoFrame.BALL_LAPS + math.pi) * (1 - (1 - t) ^ 4)
        return wheel, ball
    elseif rouletteTable.phase == PHASE.RESULT then
        return rest, 0
    end

    return rest, nil
end

local function setPocket(pocket, n)
    local color = CasinoFrame.COLORS[RouletteRules.getColor(n)]
    pocket.root:setImageColor(nil, color[1], color[2], color[3], color[4])
    pocket.label:setText(tostring(n))
end

function CasinoFrame:updateDynamic()
    local rouletteTable = self:getTable()
    if rouletteTable == nil or self.statusText == nil then
        return
    end

    local status = self:getStatusText(rouletteTable)
    if status ~= self.lastStatus then
        self.statusText:setText(status)
        self.lastStatus = status
    end

    local wheel, ball = self:getWheelRotation(rouletteTable)
    self.wheel:setImageRotation(wheel)
    self.ball:setVisible(ball ~= nil)
    if ball ~= nil then
        self.ball:setImageRotation(ball)
    end

    -- the hub shows the last number, but not while the ball is still running
    local hub = rouletteTable.history[1]
    if rouletteTable.phase == RouletteTable.PHASE.SPINNING then
        hub = nil
    end
    if hub ~= self.lastHub or self.lastHub == nil then
        self.lastHub = hub
        self.hubText:setText(hub ~= nil and tostring(hub) or "")
        if hub ~= nil then
            local color = CasinoFrame.HUB_COLORS[RouletteRules.getColor(hub)]
            self.hubText:setTextColor(color[1], color[2], color[3], color[4])
        end
    end
end

local function isWinningCell(key, result)
    local n = string.match(key, "^n(%d+)$")
    if n ~= nil then
        return tonumber(n) == result
    end
    local kind, base = RouletteRules.getBetForCell(key)
    return kind ~= nil and RouletteRules.isWin(kind, base, result)
end

function CasinoFrame:refresh()
    local rouletteTable = self:getTable()
    if rouletteTable == nil or self.cells == nil then
        return
    end

    local PHASE = RouletteTable.PHASE
    local userId, farm, isManager = self.casino:getLocalAccess()
    local mySeat = rouletteTable:findSeat(userId)
    local isBetting = rouletteTable.phase == PHASE.BETTING
    local showResult = rouletteTable.phase == PHASE.RESULT and rouletteTable.result >= 0

    -- table, chip and mode pickers
    local seatedElsewhere = nil
    for t, button in ipairs(self.tableButtons) do
        local other = self.casino:getTable(t)
        button:setText(string.format("%s (%d/%d)", getText(other.config.nameKey), other:getNumSeated(), RouletteTable.NUM_SEATS))
        button:setSelected(t == self.tableId)
        if t ~= self.tableId and other:findSeat(userId) ~= nil then
            seatedElsewhere = other
        end
    end
    for c, button in ipairs(self.chipButtons) do
        local value = rouletteTable.config.chips[c]
        button:setVisible(value ~= nil)
        if value ~= nil then
            button:setText(CasinoFrame.formatShort(value))
            button:setSelected(c == self.chipIndex)
        end
    end
    -- actions
    self.clearButton:setDisabled(mySeat == nil or not isBetting)
    self.rebetButton:setDisabled(mySeat == nil or not isBetting or self.lastBets[self.tableId] == nil)

    -- board: chips are drawn on the cell the bet was placed from, one marker per seat
    local totals = {}
    local seatsOn = {}
    for _, bet in ipairs(rouletteTable.bets) do
        local key = RouletteRules.getAnchorCell(bet.kind, bet.base)
        if key ~= nil then
            totals[key] = (totals[key] or 0) + bet.amount
            seatsOn[key] = seatsOn[key] or {}
            seatsOn[key][bet.seat] = true
        end
    end
    for key, cell in pairs(self.cells) do
        local total = totals[key]
        cell.stake:setText(total ~= nil and CasinoFrame.formatShort(total) or "")
        for s, dot in ipairs(cell.dots) do
            dot:setVisible(seatsOn[key] ~= nil and seatsOn[key][s] == true)
        end
        cell.win:setVisible(showResult and isWinningCell(key, rouletteTable.result))
    end

    -- seats: click an empty one to sit down, the button next to your own seat leaves the table
    local canSit = isManager and mySeat == nil
    for s, row in ipairs(self.seatRows) do
        local seat = rouletteTable.seats[s]
        row.swatch:setVisible(seat ~= nil)
        row.hit:setDisabled(seat ~= nil or not canSit)
        row.leave:setVisible(seat ~= nil and seat.userId == userId)
        if seat == nil then
            row.name:setText(getText(canSit and "casino_seatEmptyClick" or "casino_seatEmpty"))
            row.info:setText("")
        else
            local name = string.format("%s - %s", seat.name, seat.farmName)
            if seat.userId == userId then
                name = string.format("%s (%s)", name, getText("casino_you"))
            end
            row.name:setText(name)

            local stake = rouletteTable:getSeatStake(s)
            local round = rouletteTable.lastRound[s]
            if showResult and round ~= nil then
                row.info:setText(string.format(getText("casino_seatLast"), formatMoney(round.stake), formatMoney(round.paid)))
            elseif stake > 0 then
                row.info:setText(string.format(getText("casino_seatStake"), formatMoney(stake)))
            elseif round ~= nil then
                row.info:setText(string.format(getText("casino_seatLast"), formatMoney(round.stake), formatMoney(round.paid)))
            else
                row.info:setText(getText("casino_seatWaiting"))
            end
        end
    end

    -- history
    for h, cell in ipairs(self.historyCells) do
        local n = rouletteTable.history[h]
        cell.root:setVisible(n ~= nil)
        if n ~= nil then
            setPocket(cell, n)
        end
    end

    -- the local player's money and bets
    local myStake = mySeat ~= nil and rouletteTable:getSeatStake(mySeat) or 0
    self.balanceText:setText(string.format(getText("casino_balance"), formatMoney(Casino.getFarmBalance(farm))))
    self.stakeText:setText(string.format(getText("casino_stake"), formatMoney(myStake), formatMoney(rouletteTable.config.maxStake)))

    local lines = {}
    if mySeat ~= nil then
        for _, bet in ipairs(rouletteTable.bets) do
            if bet.seat == mySeat then
                local line = string.format("%s  %s  (%s)", RouletteRules.describe(bet.kind, bet.base, getText), formatMoney(bet.amount),
                    string.format(getText("casino_payout"), RouletteRules.getPayout(bet.kind, bet.base)))
                if showResult and RouletteRules.isWin(bet.kind, bet.base, rouletteTable.result) then
                    line = line .. "  +" .. formatMoney(bet.amount * (RouletteRules.getPayout(bet.kind, bet.base) + 1))
                end
                table.insert(lines, line)
            end
        end
        if #lines == 0 then
            lines[1] = getText("casino_noBets")
        end
    end
    local numLines = CasinoFrame.NUM_BET_LINES
    if #lines > numLines then
        local more = #lines - numLines + 1
        lines[numLines] = string.format(getText("casino_moreBets"), more)
    end
    for b, element in ipairs(self.betLines) do
        element:setText(b <= numLines and lines[b] or "")
    end

    -- hints
    if not isManager then
        self.accessText:setText(getText("casino_access_watch"))
    elseif mySeat ~= nil then
        self.accessText:setText(getText("casino_access_seated"))
    elseif seatedElsewhere ~= nil then
        self.accessText:setText(string.format(getText("casino_access_otherTable"), getText(seatedElsewhere.config.nameKey)))
    else
        self.accessText:setText(getText("casino_access_manager"))
    end

    self:updateMessage()
    self.lastStatus = nil
    self.lastHub = nil
    self:updateDynamic()
end

-- Clicks

local function nameIndex(element)
    return tonumber(string.sub(element.name or "", 2))
end

function CasinoFrame:onClickTable(element)
    local index = nameIndex(element)
    if index ~= nil and self.casino:getTable(index) ~= nil then
        self.tableId = index
        self:refresh()
    end
end

function CasinoFrame:onClickChip(element)
    local index = nameIndex(element)
    if index ~= nil then
        self.chipIndex = index
        self:refresh()
    end
end

function CasinoFrame:onClickSeatRow(element)
    local rouletteTable = self:getTable()
    local index = nameIndex(element)
    if rouletteTable == nil or index == nil or rouletteTable.seats[index] ~= nil then
        return
    end

    local userId, _, isManager = self.casino:getLocalAccess()
    if not isManager then
        self.casino:showMessage("casino_error_notManager")
    elseif rouletteTable:findSeat(userId) ~= nil then
        self.casino:showMessage("casino_error_alreadySeated")
    else
        self.casino:requestSeat(self.tableId, index, true)
    end
end

function CasinoFrame:onClickLeave()
    self.casino:requestSeat(self.tableId, 0, false)
end

function CasinoFrame:onClickClear()
    self.casino:requestBet(self.tableId, CasinoBetEvent.ACTION_CLEAR)
end

function CasinoFrame:onClickRebet()
    local bets = self.lastBets[self.tableId]
    if bets == nil or #bets == 0 then
        self.casino:showMessage("casino_error_noRebet")
        return
    end
    for _, bet in ipairs(bets) do
        self.casino:requestBet(self.tableId, CasinoBetEvent.ACTION_PLACE, bet.kind, bet.base, bet.amount)
    end
end

function CasinoFrame:onClickCell(element)
    local rouletteTable = self:getTable()
    local key = element.name
    if rouletteTable == nil or key == nil then
        return
    end

    local userId, farm, isManager = self.casino:getLocalAccess()
    local seat = rouletteTable:findSeat(userId)
    if not isManager then
        self.casino:showMessage("casino_error_notManager")
        return
    elseif seat == nil then
        self.casino:showMessage("casino_error_notSeated")
        return
    elseif rouletteTable.phase ~= RouletteTable.PHASE.BETTING then
        self.casino:showMessage("casino_error_betsClosed")
        return
    end

    local kind, base
    local n = string.match(key, "^n(%d+)$")
    if n ~= nil then
        kind, base = RouletteRules.KIND.STRAIGHT, tonumber(n)
    else
        kind, base = RouletteRules.getBetForCell(key)
    end
    local amount = rouletteTable.config.chips[self.chipIndex]
    if kind == nil or amount == nil then
        return
    end

    local stake = rouletteTable:getSeatStake(seat)
    if stake + amount > rouletteTable.config.maxStake then
        self.casino:showMessage("casino_error_maxStake")
        return
    elseif Casino.getFarmBalance(farm) - stake < amount then
        self.casino:showMessage("casino_error_noMoney")
        return
    end

    self.casino:requestBet(self.tableId, CasinoBetEvent.ACTION_PLACE, kind, base, amount)
end
